const body = $input.first().json.body || $input.first().json;

// Authentication Context Validation
if (!body.userId) {
  throw new Error('Unauthorized: Authenticated user context required');
}

return {
  json: {
    userId: body.userId,
    sessionId: body.sessionId || 'default_session',
    message: body.message || '',
    context: body.context || {},
    timestamp: new Date().toISOString()
  }
};

const data = $input.first().json;
const msg = (data.message || '').toLowerCase();

let intent = 'GENERAL';
let subIntent = 'GENERAL_QUERY';
let requiresProfile = false;
let requiresMarketData = false;
let requiresDatabase = false;

if (msg.includes('invoice') || msg.includes('bill') || msg.includes('gst')) {
  intent = 'INVOICE';
  subIntent = 'INVOICE_QUERY';
  requiresDatabase = true;
} else if (msg.includes('inventory') || msg.includes('stock') || msg.includes('sku')) {
  intent = 'INVENTORY';
  subIntent = 'INVENTORY_QUERY';
  requiresDatabase = true;
} else if (msg.includes('finance') || msg.includes('expense') || msg.includes('profit') || msg.includes('loss')) {
  intent = 'FINANCE';
  subIntent = 'FINANCE_QUERY';
  requiresDatabase = true;
} else if (msg.includes('document') || msg.includes('pdf') || msg.includes('ocr')) {
  intent = 'DOCUMENT';
  subIntent = 'DOCUMENT_QUERY';
} else if (msg.includes('scheme') || msg.includes('pmegp') || msg.includes('mudra')) {
  intent = 'SCHEME';
  subIntent = 'SCHEME_QUERY';
} else if (msg.includes('ticket') || msg.includes('support') || msg.includes('complaint')) {
  intent = 'CUSTOMER_SUPPORT';
  subIntent = 'SUPPORT_QUERY';
} else if (msg.includes('invest') || msg.includes('mutual fund') || msg.includes('sip') || msg.includes('portfolio') || msg.includes('wealth') || msg.includes('risk') || msg.includes('surplus') || msg.includes('redeem')) {
  intent = 'WEALTH';
  requiresProfile = true;
  requiresMarketData = true;
  requiresDatabase = true;

  if (msg.includes('what is') || msg.includes('explain') || msg.includes('learn')) {
    subIntent = 'WEALTH_EDUCATION';
  } else if (msg.includes('risk')) {
    subIntent = 'RISK_PROFILE';
  } else if (msg.includes('capacity') || msg.includes('earn') || msg.includes('spend')) {
    subIntent = 'INVESTMENT_CAPACITY';
  } else if (msg.includes('goal')) {
    subIntent = 'GOAL_PLANNING';
  } else if (msg.includes('suggest') || msg.includes('recommend')) {
    subIntent = 'MUTUAL_FUND_RECOMMENDATION';
  } else if (msg.includes('compare')) {
    subIntent = 'MUTUAL_FUND_COMPARE';
  } else if (msg.includes('sip')) {
    subIntent = 'SIP_CALCULATOR';
  } else if (msg.includes('lump') || msg.includes('lumpsum')) {
    subIntent = 'LUMP_SUM_CALCULATOR';
  } else if (msg.includes('portfolio') && (msg.includes('down') || msg.includes('analysis') || msg.includes('health'))) {
    subIntent = 'PORTFOLIO_ANALYSIS';
  } else if (msg.includes('portfolio')) {
    subIntent = 'PORTFOLIO';
  } else if (msg.includes('watchlist')) {
    subIntent = 'WATCHLIST';
  } else if (msg.includes('simulate') || msg.includes('invest')) {
    subIntent = 'INVESTMENT_SIMULATION';
  } else if (msg.includes('redeem')) {
    subIntent = 'REDEMPTION_SIMULATION';
  } else {
    subIntent = 'MUTUAL_FUND_SEARCH';
  }
}

return {
  json: {
    ...data,
    classification: {
      intent,
      subIntent,
      confidence: 0.96,
      requiresProfile,
      requiresMarketData,
      requiresDatabase
    }
  }
};

const item = $input.first().json;
let textResponse = '';

if (item.classification.intent === 'WEALTH') {
  textResponse = `[BizNest Wealth Orchestrator] Intent: ${item.classification.subIntent}. Based on your financial profile and capacity, mutual fund investments are subject to market risks. Past performance does not guarantee future returns.`;
} else {
  textResponse = `[BizNest AI Orchestrator] Intent: ${item.classification.intent}. Request processed successfully for user ${item.userId}.`;
}

return {
  json: {
    success: true,
    intent: item.classification.intent,
    subIntent: item.classification.subIntent,
    message: textResponse,
    data: {
      userId: item.userId,
      classification: item.classification
    },
    timestamp: new Date().toISOString()
  }
};
